1	// The page: holds one image's candidates and redraws everything from their current results.
2	// All detection and filtering is Python (detection/interactive.py) running in worker.js; this
3	// file only draws, keeps the user's settings, decisions and measurements, and asks the worker to refilter.
4	"use strict";
5	const $ = (s) => document.querySelector(s);
6	const SVGNS = "http://www.w3.org/2000/svg";
7	const STORE = "nor-filter-settings-v1"; // {values: {param: number}, off: [filter key]}; only what the user changed
8	const THEME = "nor-theme"; // "dark" | "light"; absent = follow the system
9	const MARKS = "nor-marks-v1:"; // + file name + "|" + finder: {"x,y": "in" | "out"}, the user's keepers and removals
10	const EDITS = "nor-edits-v1:"; // + file name + "|" + finder: {"x,y": {length, red, approved}}, the user's measurements
11	const SHOW = "nor-show-v1"; // the image view's Show menu
12	const CARDS = "nor-cards-v3"; // the item views' Options menu, one per view: {pass: {...}, fail: {...}}, only what the user changed
13	const BARS = "nor-bars-v1"; // {left, right}: side bar widths in pixels
14	const SOURCE = "nor-load-source"; // "local" | "drive": where Load reads from
15	const DRIVE_LINK = "nor-drive-link"; // the last Google Drive link pasted
16	const MISSING = "nor-missing-v1:"; // + file name: [[x, y]], the NoRs the user marked as missed by the finder
17	// a missing mark counts as found when a candidate lies within this distance: about half a NoR's
18	// length on the lab's slide (median 26 px), so the mark need not be placed on the NoR's centre
19	const MISSING_RADIUS = 12;
20	const MISSING_COLOUR = "#ffd400"; // yellow: none of the image's own colours
21	// where ground truth is submitted: an issue with this label, which the repo's daily intake reads
22	const REPO = "missingbulb/NoRFinder", GT_LABEL = "new-ground-truth";
23	const MEASURES = [
24	  ["length", "length", true], ["red_length", "red length", true], ["width", "width", true],
25	  ["red_over_length", "red / length", false], ["length_over_width", "length / width", false],
26	];
27	const BY_YOU = "rejected by you";
28	const SHOW_DEFAULTS = { pass: true, fails: true, nums: true, letters: true, lines: true, passW: 1, passC: "#ff69c8", failW: 1, failC: "#008cff" };
29	// each item view opens with its own options: the finalists with everything needed to check and adjust
30	// lengths, the rejected with just the NoR's borders and more context around it
31	const CARD_DEFAULTS = {
32	  pass: { pad: 4, align: true, borders: true, bars: true, lenImg: true, lenCard: false, adjust: true },
33	  fail: { pad: 10, align: false, borders: true, bars: false, lenImg: false, lenCard: false, adjust: false },
34	};
35	
36	const st = {
37	  worker: null, H: 0, W: 0, um: null, img: null, meta: null, seg: null, cands: [],
38	  fails: [], alone: null, forced: new Map(), edits: new Map(), defaults: {}, values: {}, off: new Set(),
39	  about: {}, detectValues: {}, lastRun: null, filtersFor: null, seq: 0, inflight: false, pending: false,
40	  zoom: 2, fileName: "", sha: "", source: null, missing: [], numbers: new Map(), order: [], times: {}, sel: null, tab: "pass",
41	  show: { ...SHOW_DEFAULTS, ...readJSON(SHOW) }, opt: readOpts(), crops: new Map(),
42	};
43	
44	function readJSON(key, fallback = {}) {
45	  try { return JSON.parse(localStorage.getItem(key)) || fallback; } catch { return fallback; }
46	}
47	function readOpts() {
48	  const saved = readJSON(CARDS);
49	  return { pass: { ...CARD_DEFAULTS.pass, ...saved.pass }, fail: { ...CARD_DEFAULTS.fail, ...saved.fail } };
50	}
51	// the options a candidate's card is drawn with: those of the view it is listed in
52	const optsOf = (c) => st.opt[result(c.i) === null ? "pass" : "fail"];
53	function writeJSON(key, v) {
54	  try { localStorage.setItem(key, JSON.stringify(v)); } catch { /* private mode: lasts for this page only */ }
55	}
56	
57	// ---------- saved filter settings ----------
58	const loadSaved = () => readJSON(STORE, { values: {}, off: [] });
59	function save() {
60	  const values = {};
61	  for (const [k, v] of Object.entries(st.values)) if (v !== st.defaults[k]) values[k] = v;
62	  writeJSON(STORE, { values, off: [...st.off] });
63	}
64	
65	// ---------- the user's decisions and measurements: saved per file and finder, tied to each candidate's position ----------
66	const posKey = (c) => `${Math.round(c.cx)},${Math.round(c.cy)}`;
67	const fileKey = () => st.fileName + "|" + st.meta.finder;
68	function loadMarks() {
69	  st.forced = new Map(); st.edits = new Map();
70	  const marks = readJSON(MARKS + fileKey()), edits = readJSON(EDITS + fileKey());
71	  for (const c of st.cands) {
72	    const m = marks[posKey(c)], e = edits[posKey(c)];
73	    if (m) st.forced.set(c.i, m);
74	    if (e) st.edits.set(c.i, e);
75	  }
76	}
77	function saveMap(prefix, map) {
78	  const out = {};
79	  for (const [j, v] of map) out[posKey(st.cands[j])] = v;
80	  writeJSON(prefix + fileKey(), out);
81	}
82	// the user's word on a candidate: "approve" (a NoR, with the lengths shown), "reject" (not one), or null (the filters decide)
83	function decide(i, d) {
84	  d ? st.forced.set(i, d === "approve" ? "in" : "out") : st.forced.delete(i);
85	  const e = { ...(st.edits.get(i) || {}) };
86	  d === "approve" ? (e.approved = true) : delete e.approved;
87	  Object.keys(e).length ? st.edits.set(i, e) : st.edits.delete(i);
88	  saveMap(MARKS, st.forced); saveMap(EDITS, st.edits); render();
89	}
90	function edit(i, change) {
91	  const e = { ...(st.edits.get(i) || {}), ...change };
92	  for (const k of Object.keys(e)) if (e[k] == null || e[k] === false) delete e[k];
93	  Object.keys(e).length ? st.edits.set(i, e) : st.edits.delete(i);
94	  saveMap(EDITS, st.edits); drawLines(st.cands[i]); render();
95	}
96	
97	// ---------- status ----------
98	function status(text, err) {
99	  const s = $("#status"); s.textContent = text; s.classList.toggle("err", !!err);
100	  if (st.busySince) $("#busy-text").textContent = text;
101	  if (err) busy(false);
102	}
103	// the spinner and elapsed time shown while Python loads or a finder runs. look "scan": a finder running over
104	// an image shows a photocopier's light sweeping across it instead of the spinner; "peek": the image painting
105	// as it arrives stays in view, the text in a pill below it
106	function busy(on, text, look) {
107	  clearInterval(st.busyTimer); st.busySince = on ? st.busySince || Date.now() : 0;
108	  $("#spin").classList.toggle("on", on); $("#busy").hidden = !on;
109	  $("#busy").classList.toggle("scan", on && look === "scan"); $("#busy").classList.toggle("peek", on && look === "peek");
110	  if (!on) return;
111	  $("#busy-text").textContent = text || $("#status").textContent; $("#busy-time").textContent = "";
112	  st.busyTimer = setInterval(() => { $("#busy-time").textContent = ((Date.now() - st.busySince) / 1000).toFixed(0) + " s"; }, 500);
113	}
114	function statusBar() {
115	  const t = st.times, parts = [];
116	  if (t.load != null) parts.push(`Python ${t.load.toFixed(0)} s`);
117	  if (t.open != null) parts.push(`image ${t.open.toFixed(1)} s`);
118	  if (t.detect != null) parts.push(`finding ${t.detect.toFixed(1)} s`);
119	  if (t.filter != null) parts.push(`filters ${t.filter.toFixed(0)} ms`);
120	  $("#sb-times").textContent = parts.join(" · ");
121	  $("#sb-file").textContent = st.fileName || "No image";
122	}
123	const fmt = (v, d = 2) => (v == null || !isFinite(v) ? "–" : Number(v).toFixed(d));
124	
125	// ---------- worker ----------
126	async function start() {
127	  if ("serviceWorker" in navigator) {
128	    try {
129	      await navigator.serviceWorker.register("sw.js");
130	      await navigator.serviceWorker.ready;
131	      if (!navigator.serviceWorker.controller) {
132	        // first visit: wait for the cache to take control so the downloads below are kept
133	        await Promise.race([new Promise((r) => navigator.serviceWorker.addEventListener("controllerchange", r, { once: true })),
134	                            new Promise((r) => setTimeout(r, 3000))]);
135	      }
136	    } catch (e) { console.warn("no cache for third-party files:", e); }
137	  }
138	  status("Loading Python in the background…"); $("#spin").classList.add("on");
139	  st.worker = new Worker("worker.js", { type: "module" });
140	  st.worker.onmessage = (e) => onWorker(e.data);
141	}
142	
143	function onWorker(m) {
144	  if (m.type === "progress") status(m.text);
145	  else if (m.type === "error") status("Error: " + m.text, true);
146	  else if (m.type === "ready") {
147	    const sel = $("#finder");
148	    sel.innerHTML = Object.entries(m.finders).map(([k, v]) => `<option value="${k}">${v}</option>`).join("");
149	    sel.disabled = false; st.ready = true; $("#spin").classList.remove("on");
150	    st.about = m.about; st.times.load = m.secs; st.help = Object.values(m.about)[0].help;
151	    buildDetect(); useFilters(sel.value); statusBar();
152	    status("Ready. Load an image.");
153	    if (st.queued) { const q = st.queued; st.queued = null; send(q.name, q.bytes); }
154	  } else if (m.type === "opened") {
155	    st.H = m.H; st.W = m.W; st.um = m.um; const n = m.H * m.W;
156	    st.img = { r: m.images.subarray(0, n), g: m.images.subarray(n, 2 * n), b: m.images.subarray(2 * n, 3 * n) };
157	    st.plain = null; st.peeked = false; drawBase(); $("#empty").hidden = true; $("#stage").hidden = false; $("#thumb-wrap").hidden = false;
158	    setZoom(st.zoom);
159	    busy(false); st.times.open = m.secs; st.times.detect = st.times.filter = null; statusBar();
160	    showView("image"); updateFind(); fold(true); loadShine(); drawMissing();
161	    status("Image loaded. Press Find Candidates.");
162	    if (st.source && st.source.kind === "local") notice(LOCAL_GT);
163	  } else if (m.type === "detected") {
164	    busy(false);
165	    st.times.detect = m.secs; st.lastRun = st.running; st.running = null;
166	    onDetected(m.meta, m.seg); statusBar(); updateFind();
167	    status(m.meta.exact_refilter ? "Done." : "This finder picks between alternatives using the filters, so after a filter change press Find Candidates again for its exact result.");
168	  } else if (m.type === "filtered") {
169	    st.inflight = false;
170	    if (m.seq === st.seq) { st.fails = m.fails; st.alone = m.alone; st.times.filter = m.ms; statusBar(); render(); }
171	    if (st.pending) { st.pending = false; refilter(); }
172	  }
173	}
174	
175	function detect() {
176	  const finder = $("#finder").value, overrides = detectOverrides(finder);
177	  st.running = runKey(); st.runOverrides = overrides; $("#find").disabled = true; $("#find").classList.remove("shine");
178	  busy(true, "Finding candidates…", "scan");
179	  st.worker.postMessage({ type: "detect", finder, overrides });
180	}
181	
182	function refilter() {
183	  if (!st.meta) return;
184	  if (st.inflight) { st.pending = true; return; }
185	  st.inflight = true;
186	  st.worker.postMessage({ type: "refilter", seq: ++st.seq, spec: { values: st.values, off: [...st.off] } });
187	}
188	
189	// ---------- loading ----------
