547	  const kind = typeof def === "boolean" ? "bool" : typeof def === "number" ? "number" : "text";
548	  const p = document.createElement("div"); p.className = "param " + kind; p.dataset.name = name;
549	  let slider = "";
550	  if (kind === "number") {
551	    const [lo, hi, step] = paramRange(name, def), at = Math.min(1, Math.max(0, (def - lo) / (hi - lo)));
552	    slider = `<div class="slide"><input type="range" min="${lo}" max="${hi}" step="${step}"><button type="button" class="ours" style="--at:${at}"
553	      title="Ours: ${def}. Click to go back to it" aria-label="Back to ours, ${def}"></button></div>`;
554	  }
555	  const box = kind === "bool" ? '<input type="checkbox">' : kind === "number" ? '<input type="number" step="any" class="box">' : '<input type="text" class="box">';
556	  p.innerHTML = `<span class="name">${name} ${helpIcon(name)}</span>${slider}${box}`;
557	  const range = p.querySelector('input[type="range"]'), inp = p.querySelector(".box, input[type=checkbox]");
558	  p.set = (v) => {
559	    if (kind === "bool") inp.checked = v; else inp.value = kind === "text" ? JSON.stringify(v) : v;
560	    if (range) range.value = v;
561	    p.classList.toggle("changed", JSON.stringify(v) !== JSON.stringify(def));
562	  };
563	  const take = (raw) => {
564	    let v;
565	    try { v = kind === "bool" ? raw : kind === "number" ? parseFloat(raw) : JSON.parse(raw); } catch { return; }
566	    if (kind === "number" && !isFinite(v)) return;
567	    if (range) range.value = v; if (kind === "number" && document.activeElement !== inp) inp.value = v;
568	    p.classList.toggle("changed", JSON.stringify(v) !== JSON.stringify(def));
569	    onset(v);
570	  };
571	  inp.oninput = inp.onchange = () => take(kind === "bool" ? inp.checked : inp.value);
572	  if (range) range.oninput = () => { inp.value = range.value; take(range.value); };
573	  if (range) p.querySelector(".ours").onclick = () => { p.set(def); onset(def); };
574	  p.set(value);
575	  return p;
576	}
577	// the filters and their values for a finder: our numbers, overlaid with what this browser saved
578	function useFilters(finder) {
579	  const about = st.about[finder], saved = loadSaved();
580	  st.filtersFor = finder; st.filters = about.filters; st.reasons = about.reasons;
581	  st.defaults = {}; st.values = {};
582	  for (const f of about.filters) for (const [k, v] of Object.entries(f.params)) st.defaults[k] = v;
583	  for (const k in st.defaults) st.values[k] = k in saved.values ? saved.values[k] : st.defaults[k];
584	  st.off = new Set(saved.off.filter((k) => about.filters.some((f) => f.key === k)));
585	  buildFilters(); $("#reset-filters").disabled = false;
586	}
587	
588	function buildFilters() {
589	  const box = $("#filters"); box.innerHTML = "";
590	  for (const f of st.filters) {
591	    const d = document.createElement("div"); d.className = "filter"; d.dataset.key = f.key;
592	    d.innerHTML = `<label class="top"><input type="checkbox" ${st.off.has(f.key) ? "" : "checked"}>
593	      <span class="badge" style="--c:${colour(f.key)}">${f.letter}</span><span class="title">${esc(f.title)}</span>
594	      <span class="n" title="X (Y): what this filter rejects&#10;X: candidates that pass every other filter that is on and fail only this one, so switching it off lets them through.&#10;Y: every candidate that fails this filter, whatever the others say."></span></label><div class="desc">${esc(f.text)}</div>`;
595	    d.querySelector("input").onchange = (e) => {
596	      e.target.checked ? st.off.delete(f.key) : st.off.add(f.key); d.classList.toggle("off", !e.target.checked); save(); refilter();
597	    };
598	    d.classList.toggle("off", st.off.has(f.key));
599	    for (const name of Object.keys(f.params)) {
600	      d.append(dial(name, st.defaults[name], st.values[name], (v) => {
601	        st.values[name] = v;
602	        document.querySelectorAll(`#filters .param[data-name="${name}"]`).forEach((o) => { if (!o.contains(document.activeElement)) o.set(v); });
603	        save(); refilter();
604	      }));
605	    }
606	    box.append(d);
607	  }
608	}
609	
610	// the finder's settings: its main ones on show, every one under Advanced; both edit the same values
611	function buildDetect() {
612	  const finder = $("#finder").value, about = st.about[finder];
613	  const defs = about.detection_params, vals = (st.detectValues[finder] ||= { ...defs });
614	  $("#finder-note").textContent = about.about + (about.exact_refilter ? "" : " It picks between alternatives using the filters, so after a filter change, find again for its exact result.");
615	  const row = (k) => dial(k, defs[k], vals[k], (v) => {
616	    vals[k] = v;
617	    document.querySelectorAll(`#main-params .param[data-name="${k}"], #detect-params .param[data-name="${k}"]`).forEach((o) => { if (!o.contains(document.activeElement)) o.set(v); });
618	    updateFind();
619	  });
620	  $("#main-params").replaceChildren(...about.main_params.map(row));
621	  $("#detect-params").replaceChildren(...Object.keys(defs).map(row));
622	  updateFind();
623	}
624	
625	function detectOverrides(finder) {
626	  const o = {}, defs = st.about[finder].detection_params;
627	  for (const [k, v] of Object.entries(st.detectValues[finder] || {})) if (JSON.stringify(v) !== JSON.stringify(defs[k])) o[k] = v;
628	  return o;
629	}
630	const runKey = () => JSON.stringify([$("#finder").value, detectOverrides($("#finder").value)]);
631	// Find Candidates shines while the finder or its settings differ from what the image was last searched with
632	function updateFind() {
633	  const finder = $("#finder").value; if (!st.about[finder]) return;
634	  const o = detectOverrides(finder), f = $("#find");
635	  $("#reset-detect").disabled = !Object.keys(o).length;
636	  f.disabled = !st.img || !!st.running;
637	  f.classList.toggle("shine", !f.disabled && runKey() !== st.lastRun);
638	}
639	
640	// ---------- drawing ----------
641	function render() {
642	  const passes = [], rejects = [], counts = {};
643	  for (const c of st.order) {
644	    const r = result(c.i), cls = r === null ? "pass" : "fail";
645	    c.el.setAttribute("class", cls + (st.forced.has(c.i) ? " forced" : ""));
646	    const let_ = c.text.lastChild;
647	    if (r === null) { let_.textContent = ""; passes.push(c); }
648	    else { const R = reasonOf(r); let_.textContent = R.letter; let_.setAttribute("fill", `rgb(${R.color})`); rejects.push(c); counts[r] = (counts[r] || 0) + 1; }
649	  }
650	  st.passes = passes; st.rejects = rejects;
651	  document.querySelectorAll(".filter").forEach((d) => {
652	    const k = d.dataset.key;
653	    d.querySelector(".n").innerHTML = st.alone ? `${THUMB} ${st.alone.only[k] ?? 0} (${st.alone.counts[k] ?? 0})` : "";
654	  });
655	  $("#sb-counts").innerHTML = `<b>${st.order.length}</b> candidates · <b>${passes.length}</b> finalists`;
656	  $("#n-pass").textContent = passes.length; $("#n-fail").textContent = rejects.length;
657	  if (st.view === "items") renderList();
658	  renderSummary(passes, counts); renderSelected(); placeRing(); downloads(true);
659	}
660	
661	// ---------- cards: one per candidate, in the item views and as the selection ----------
662	// The crop, turned so the NoR lies level when "align to horizon" is on, with its outlines, bars and
663	// length handles drawn over it. Cached until the options or the candidate's lengths change.
664	function crop(c, size) {
665	  const o = optsOf(c), key = JSON.stringify([size, o, st.edits.get(c.i) || null, st.show.passC, st.show.failC, result(c.i) === null]);
666	  const hit = st.crops.get(c.i + "|" + size);
667	  if (hit && hit.key === key) return hit.node;
668	  const L = linesOf(c), pad = o.pad;
669	  let th = 0, cx = (c.bb[0] + c.bb[2]) / 2, cy = (c.bb[1] + c.bb[3]) / 2;
670	  if (L) {
671	    const [[a, b], [p, q]] = L.length; cx = (a + p) / 2; cy = (b + q) / 2;
672	    if (o.align) { th = Math.atan2(q - b, p - a); if (Math.cos(th) < 0) th += Math.PI; }
673	  }
674	  const ax = [Math.cos(th), Math.sin(th)], nv = [-Math.sin(th), Math.cos(th)];
675	  const toUV = ([x, y]) => [(x - cx) * ax[0] + (y - cy) * ax[1], (x - cx) * nv[0] + (y - cy) * nv[1]];
676	  const toXY = ([u, v]) => [cx + u * ax[0] + v * nv[0], cy + u * ax[1] + v * nv[1]];
677	  // extent: every pixel of the candidate, and its lines
678	  let u0 = Infinity, u1 = -Infinity, v0 = Infinity, v1 = -Infinity;
679	  const take = (p) => { const [u, v] = toUV(p); u0 = Math.min(u0, u); u1 = Math.max(u1, u); v0 = Math.min(v0, v); v1 = Math.max(v1, v); };
680	  for (let y = 0; y < c.h; y++) for (let x = 0; x < c.w; x++) if (c.blk[y * c.w + x]) for (const [dx, dy] of [[0, 0], [1, 0], [0, 1], [1, 1]]) take([c.x0 + x + dx, c.y0 + y + dy]);
681	  if (L) for (const k of ["length", "red"]) L[k].forEach(take);
682	  u0 -= pad; u1 += pad; v0 -= pad; v1 += pad;
683	  const uw = u1 - u0, vw = v1 - v0, s = Math.max(2, Math.min(size / 10, size / Math.max(uw, vw))), dpr = devicePixelRatio || 1;
684	  const cv = document.createElement("canvas"); cv.width = Math.round(uw * s * dpr); cv.height = Math.round(vw * s * dpr);
685	  cv.style.width = uw * s + "px";
686	  const ctx = cv.getContext("2d"); ctx.imageSmoothingEnabled = false;
687	  ctx.fillStyle = "#000"; ctx.fillRect(0, 0, cv.width, cv.height);
688	  ctx.setTransform(s * dpr, 0, 0, s * dpr, 0, 0); ctx.translate(-u0, -v0);
689	  ctx.transform(ax[0], nv[0], ax[1], nv[1], 0, 0); ctx.translate(-cx, -cy);
690	  const R = Math.ceil(Math.hypot(uw, vw) / 2) + 2, sx = Math.max(0, Math.floor(cx - R)), sy = Math.max(0, Math.floor(cy - R));
691	  const sw = Math.min(st.W, Math.ceil(cx + R)) - sx, sh = Math.min(st.H, Math.ceil(cy + R)) - sy;
692	  ctx.drawImage(st.plain, sx, sy, sw, sh, sx, sy, sw, sh);
693	  if (o.borders) {
694	    ctx.lineWidth = 1 / s; ctx.strokeStyle = result(c.i) === null ? st.show.passC : st.show.failC;
695	    for (const [val, alpha] of [[1, 0.5], [2, 0.7]]) { ctx.globalAlpha = alpha; ctx.stroke(new Path2D(outline(c, c.blk, val))); }
696	    ctx.globalAlpha = 1;
697	  }
698	  const node = document.createElement("div"); node.className = "crop"; node.append(cv);
699	  if (L && (o.bars || o.lenImg || o.adjust)) node.append(cropMarks(c, L, { s, u0, v0, uw, vw, toUV, toXY, ax }));
700	  st.crops.set(c.i + "|" + size, { key, node }); return node;
701	}
702	
703	// bars, length labels and draggable ends over a crop, in its own turned coordinates
704	function cropMarks(c, L, g) {
705	  const o = optsOf(c), f = st.um || 1, svg = el("svg", { class: "marks", viewBox: `${g.u0} ${g.v0} ${g.uw} ${g.vw}`, width: g.uw * g.s, height: g.vw * g.s });
706	  const px = 1 / g.s, line = (k, cls) => { const [[a, b], [p, q]] = L[k].map(g.toUV); return el("line", { x1: a, y1: b, x2: p, y2: q, class: cls }); };
707	  const draw = () => {
708	    svg.replaceChildren();
709	    if (o.bars) svg.append(line("length", "bar"), line("width", "bar"), line("red", "bar r"));
710	    if (o.lenImg) {
711	      for (const [k, cls, dy] of [["length", "", -5], ["red", "r", 11]]) {
712	        const [[a, b], [p, q]] = L[k].map(g.toUV), t = el("text", { x: (a + p) / 2, y: Math.min(b, q) + dy * px, class: cls, "font-size": 10 * px, "stroke-width": 2 * px });
713	        t.textContent = fmt(dist(L[k]) * f, 1); svg.append(t);
714	      }
715	    }
716	    if (o.adjust && result(c.i) === null) for (const k of ["length", "red"]) L[k].forEach((p, j) => {
717	      const [u, v] = g.toUV(p), h = el("circle", { cx: u, cy: v, r: 4 * px, class: "handle" + (k === "red" ? " r" : ""), "stroke-width": px });
718	      h.dataset.k = k; h.dataset.j = j; svg.append(h);
719	    });
720	  };
721	  draw();
722	  // an end slides along its own line; the result is kept in image coordinates
723	  svg.addEventListener("pointerdown", (e) => {
724	    const h = e.target.closest(".handle"); if (!h) return;
725	    e.preventDefault(); e.stopPropagation(); svg.setPointerCapture(e.pointerId);
726	    const k = h.dataset.k, j = +h.dataset.j, [A, B] = L[k], d = [B[0] - A[0], B[1] - A[1]], n = Math.hypot(...d), dir = [d[0] / n, d[1] / n];
727	    L = { ...L, [k]: [[...A], [...B]] };
728	    const move = (ev) => {
729	      const pt = svg.createSVGPoint(); pt.x = ev.clientX; pt.y = ev.clientY;
730	      const q = pt.matrixTransform(svg.getScreenCTM().inverse()), P = g.toXY([q.x, q.y]);
731	      let t = (P[0] - A[0]) * dir[0] + (P[1] - A[1]) * dir[1];
732	      t = j === 0 ? Math.min(t, n - 1) : Math.max(t, 1);
733	      L[k][j] = [A[0] + t * dir[0], A[1] + t * dir[1]]; draw();
734	    };
735	    const up = () => {
736	      svg.removeEventListener("pointermove", move); svg.removeEventListener("pointerup", up);
737	      edit(c.i, { [k]: L[k].map((p) => p.map((v) => Math.round(v * 100) / 100)) });
738	    };
739	    svg.addEventListener("pointermove", move); svg.addEventListener("pointerup", up);
740	  });
741	  return svg;
742	}
743	
744	// thumbs up and down (paths from Lucide, ISC licence): the user's own verdict on a candidate
745	const THUMB = `<svg viewBox="0 0 24 24" width="16" height="16" aria-hidden="true"><path d="M7 10v12"/><path d="M15 5.88 14 10h5.83a2 2 0 0 1 1.92 2.56l-2.33 8A2 2 0 0 1 17.5 22H4a2 2 0 0 1-2-2v-8a2 2 0 0 1 2-2h2.76a2 2 0 0 0 1.79-1.11L12 2a3.13 3.13 0 0 1 3 3.88Z"/></svg>`;
746	const GOTO = `<svg viewBox="0 0 24 24" width="16" height="16"><circle cx="12" cy="12" r="7"/><circle cx="12" cy="12" r="2" class="dot"/><path d="M12 1.5v4M12 18.5v4M1.5 12h4M18.5 12h4"/></svg>`;
747	function card(c, where) {
748	  const r = result(c.i), f = st.forced.get(c.i), d = document.createElement("div");
749	  d.className = "card " + (r === null ? "pass" : "fail") + (f === "in" ? " approved" : f === "out" ? " byyou" : "") +
750	    (where === "list" && c.i === st.sel ? " selected" : "");
751	  d.dataset.i = c.i;
752	  const state = r === null ? "Finalist" : "Rejected";
753	  d.innerHTML = `<div class="head"><span class="num">#${st.numbers.get(c.i)}</span><span class="state">${state}</span>
754	    <span class="verdict" role="group" aria-label="Your verdict"></span></div>`;
755	  const acts = d.querySelector(".verdict");
756	  const btn = (cls, on, title, fn) => {
757	    const b = document.createElement("button"); b.type = "button"; b.className = cls + (on ? " on" : ""); b.innerHTML = THUMB;
758	    b.title = title; b.setAttribute("aria-label", title); b.setAttribute("aria-pressed", on);
759	    b.onclick = (e) => { e.stopPropagation(); st.sel = c.i; fn(); }; acts.append(b);
760	  };
761	  btn("up", f === "in", f === "in" ? "You said this is a NoR. Click to undo" : "A NoR: keep it, with its lengths as shown (saved as ground truth)",
762	    () => decide(c.i, f === "in" ? null : "approve"));
763	  btn("down", f === "out", f === "out" ? "You said this is not a NoR. Click to let the filters decide again" : "Not a NoR: reject it (saved as ground truth)",
764	    () => decide(c.i, f === "out" ? null : "reject"));
765	  if (where === "list") d.onclick = () => select(c.i);
766	  const wrap = document.createElement("div"); wrap.className = "crop-wrap";
767	  wrap.append(crop(c, where === "selected" ? 320 : 170));
768	  wrap.insertAdjacentHTML("beforeend", `<button class="goto" title="Show it on the image" aria-label="Show it on the image">${GOTO}</button>`);
769	  wrap.querySelector(".goto").onclick = () => { select(c.i); showView("image"); focusOn(c); };
770	  d.append(wrap);
771	  const e = st.edits.get(c.i) || {};
772	  if (e.length || e.red) {
773	    d.insertAdjacentHTML("beforeend", `<div class="tag">Lengths adjusted <button class="link">reset</button></div>`);
774	    d.querySelector(".tag button").onclick = () => edit(c.i, { length: null, red: null });
775	  }
776	  if (r !== null) d.insertAdjacentHTML("beforeend", `<div class="why">${whyAll(c).map((k) => `<span><b class="lt" style="--c:${colour(k)}">${reasonOf(k).letter}</b> ${esc(reasonOf(k).title)}</span>`).join("")}</div>`);
777	  if (optsOf(c).lenCard && c.m) {
778	    const t = document.createElement("table");
779	    t.innerHTML = measures(c).map(([l, v]) => `<tr><td>${l}</td><td>${fmt(v)}</td></tr>`).join("");
780	    d.append(t);
781	  }
782	  return d;
783	}
784	
785	function renderList() {
786	  if (st.tab === "missing") {
787	    $("#list").replaceChildren(...st.missing.map(missingCard));
788	    if (!st.missing.length) $("#list").innerHTML = `<p class="dim">No missing candidates. Right-click the image where the finder missed a NoR to mark one.</p>`;
789	    return;
790	  }
791	  const items = st.tab === "pass" ? st.passes || [] : st.rejects || [];
792	  $("#list").replaceChildren(...items.map((c) => card(c, "list")));
793	  if (!items.length) $("#list").innerHTML = `<p class="dim">${st.tab === "pass" ? "No finalists." : "Nothing rejected."}</p>`;
794	}
795	
796	// ---------- selection ----------
797	function select(i) {
798	  st.sel = i; renderSelected(); placeRing();
799	  document.querySelectorAll("#list .card").forEach((d) => d.classList.toggle("selected", +d.dataset.i === i));
800	}
801	// in the item views, the selected candidate's card is brought into sight, on the tab that lists it
802	function revealSelected(block) {
803	  if (st.sel == null || !st.meta) return;
804	  const t = result(st.sel) === null ? "pass" : "fail";

