const A = await (await fetch("answers/answers.json")).json();
const bin = async (n) => new Uint8Array(await (await fetch("answers/" + n)).arrayBuffer());
let finder;
postMessage({ type: "ready", finders: A.finders, about: A.about, secs: 0 });
onmessage = async ({ data: m }) => {
  if (m.type === "open") { const images = await bin("images.bin"); postMessage({ type: "opened", H: A.H, W: A.W, um: A.um, images, secs: 0 }, [images.buffer]); }
  else if (m.type === "detect") { finder = m.finder; const seg = await bin("seg_" + finder + ".bin"); postMessage({ type: "detected", meta: A.detected[finder], seg, secs: 0 }, [seg.buffer]); }
  else if (m.type === "refilter") postMessage({ type: "filtered", ...A.filtered[finder][0], seq: m.seq, ms: 0 });
