export default async (page, shot) => {
  await page.click("#notice-ok").catch(() => {});
  await page.click("#find");
  await page.waitForFunction(() => st.alone && $("#busy").hidden);
  await page.evaluate(() => setZoom(4));
  const b = await page.locator("#base").boundingBox();
  const at = { x: 60, y: 60 };
  await page.evaluate(({ x, y }) => { const sc = $("#scroller"); sc.scrollTo(x * st.zoom - sc.clientWidth / 2, y * st.zoom - sc.clientHeight / 2); }, at);
  await page.waitForTimeout(200);
  const p = await page.evaluate(({ x, y }) => { const r = $("#base").getBoundingClientRect(); return { sx: r.left + x * st.zoom, sy: r.top + y * st.zoom }; }, at);
  await page.mouse.click(p.sx, p.sy, { button: "right" });
  console.log("menu: " + await page.textContent("#ctx button"));
  await page.click("#ctx button");
  console.log(JSON.stringify(await page.evaluate(() => ({ sel: st.sel, added: st.added }))));
  await page.waitForTimeout(400);
  await shot("a1_page", null);
  await shot("a2_card", "#selected .card");
  // drag the right green end
  const hb = await page.locator('#selected .handle[data-k="length"][data-j="1"]').boundingBox();
  await page.mouse.move(hb.x + hb.width / 2, hb.y + hb.height / 2); await page.mouse.down();
  await page.mouse.move(hb.x + 40, hb.y - 30, { steps: 6 }); await page.mouse.up(); await page.waitForTimeout(100);
  await shot("a3_adjusted", "#selected .card");
  await page.click("#switch"); await page.waitForTimeout(200);
  await shot("a4_list", "#items-view");
  await page.click("#selected .verdict .up"); await page.waitForTimeout(200);
  await shot("a5_list_approved", "#items-view");
  await page.click("#switch"); await page.waitForTimeout(300);
  await shot("a6_image_after", "#scroller");
  console.log("glow circles: " + await page.$$eval("#overlay .added .glow", (c) => c.length));
  const [dl] = await Promise.all([page.waitForEvent("download"), page.click("#dl-truth")]);
  const fs = await import("node:fs"); const gt = JSON.parse(fs.readFileSync(await dl.path(), "utf8"));
  console.log(JSON.stringify(gt.labels.filter((L) => L.kind)));
};
EOF
