  await check(miss.label === 1 && miss.radius_px > 0, `a missing mark is a real NoR with its radius (${miss.radius_px} px)`);''','''  const miss = gt.labels.find((L) => L.kind === "missing");
  await check(miss.label === 1 && miss.radius_px > 0 && miss.origin === "added by user" && miss.width_px > 0 && miss.lines.width,
    `an added NoR is a real NoR with its radius, its origin and its measurements (${miss.radius_px} px, ${miss.width_px.toFixed(1)} px wide)`);''')
R('''/Only the candidates you marked/.test(note)''','''/Only the candidates you marked/.test(note)''')
open(p,'w').write(s)
